evaluateBeanshell.condition:
boolean edition = true;
if (!"${variant.suffix}".isEmpty()) {
  java.util.Properties release = new java.util.Properties();
  java.io.Reader reader = new java.io.FileReader(new java.io.File(System.getProperty("java.home"), "release"));
  try {
    release.load(reader);
  } finally {
    reader.close();
  }
  String implementor = release.getProperty("IMPLEMENTOR", "");
  String version = release.getProperty("GRAALVM_VERSION", "");
  edition = implementor.equals("\"Oracle Corporation\"") && version.equals("\"${graalvm.version}\"");
  if (!edition) {
    System.err.println("[ERROR] The release file of " + System.getProperty("java.home") + ": IMPLEMENTOR="
      + implementor + ", GRAALVM_VERSION=" + version);
  }
}
edition;
